package signature

// presigning.go — the allowlist of releases published before signing began (D-0841).
//
// Purpose: the signed-since floor alone lets a compromised registry serve a slug at a forged older version, or under the other tier, unsigned with a matching checksum. This list names the real pre-signing (version, sha256) pairs per tier and slug, so an unsigned release that is not on it is refused in both compat modes.
// Inputs: the "presigning" object of signed_since.json (GENERATED by scripts/gen-signed-since.sh from the release history the floor is built from): tier -> slug -> [{version, sha256}].
// Outputs: Presigning, UnsignedAllowed.
// Constraints: the rule binds a slug only once the floor or this list names it in ANY tier, so a slug the data never mentions (and today's empty data) keeps the ordinary unsigned rule. The lookup is by (tier, slug) pair: a slug released in both tiers (cron, notify) is allowed only for the pairs listed under the tier the entry claims. An unreadable file fails closed.

import (
	"encoding/json"
	"strings"
)

// PresigningRelease is one release that existed before signing began.
type PresigningRelease struct {
	Version string `json:"version"`
	SHA256  string `json:"sha256"`
}

// Presigning maps tier -> slug -> pre-signing releases. Tests swap it with
// signaturetest.UsePresigning.
var Presigning, presigningErr = loadPresigning(signedSinceJSON)

// loadPresigning decodes the optional "presigning" object. A missing object is
// an empty list; a malformed one is an error and UnsignedAllowed then refuses.
func loadPresigning(data []byte) (map[string]map[string][]PresigningRelease, error) {
	var doc struct {
		Presigning map[string]map[string][]PresigningRelease `json:"presigning"`
	}
	if err := json.Unmarshal(data, &doc); err != nil {
		return nil, err
	}
	return doc.Presigning, nil
}

// UnsignedAllowed reports whether an unsigned release of tier/slug/version with
// archive digest sha256 may proceed to the ordinary unsigned rule. It is false
// when the floor or the pre-signing list names the slug (in any tier) and this
// exact (tier, slug, version, sha256) is not on the list.
func UnsignedAllowed(tier, slug, version, sha256 string) bool {
	if floorErr != nil || presigningErr != nil {
		return false
	}
	if !slugNamed(slug) {
		return true
	}
	for _, r := range Presigning[tier][slug] {
		if r.Version == version && strings.EqualFold(r.SHA256, sha256) && sha256 != "" {
			return true
		}
	}
	return false
}

// slugNamed reports whether any tier's floor or pre-signing list names slug.
func slugNamed(slug string) bool {
	for _, m := range Floor {
		if _, ok := m[slug]; ok {
			return true
		}
	}
	for _, m := range Presigning {
		if len(m[slug]) > 0 {
			return true
		}
	}
	return false
}
